import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

import type * as React from "react";

/**
 * The Sistine material system — the single source of the material → markup mapping.
 *
 * FOUR materials (glass, frosted, crystal, opaque), each a `[data-material]` token set in
 * app/theme/materials.css, composed with orthogonal AXES (border, veil, size, gradient, glow, sheen)
 * over the one structural `glass` utility. Components call `glassMaterial()` instead of hardcoding
 * recipe class strings (check-theme bans the legacy `glass-bg`/`glass-surface`/… classes).
 *
 * Semantics:
 * - `material` UNDEFINED = adaptive: no attribute is rendered; the surface follows the page's
 *   [data-glass] style (the default everywhere).
 * - An explicit material PINS the element under any page style, and — because the token set is
 *   inherited custom properties — also acts as a scoped default for adaptive glass descendants
 *   (a dialog set to frosted re-skins the controls inside it; pin a child back with its own material).
 * - `"none"` = not a glass surface: the helper returns nothing and the component supplies its plain
 *   (shadcn) classes.
 */
export type Material = "glass" | "frosted" | "crystal" | "opaque" | "none";

export interface MaterialProps {
  /** undefined = adaptive (follows the page style); "none" = the component's plain fallback. */
  material?: Material;
  /** Material border. Three weights: `true`/"hairline" = the material's edge (1px; 0.5px under
   *  frosted), "rim" = 2px, "frame" = 4px. */
  border?: boolean | "hairline" | "rim" | "frame";
  /** Element-composed legibility floor for read-through overlays (menus, tooltips, toasts). */
  veil?: boolean;
  /** Blur/elevation tier — INTERNAL: set by a component's ROLE (glass-sm/-lg), not a public prop
   *  ("size" universally means a component's dimensions; the material tier must never shadow that). */
  size?: "sm" | "lg" | "xl";
  /** Readability blur FLOOR (>= --glass-diffuse, default 12px) for text-dense translucent surfaces;
   *  inert under opaque. "stained" = the dyed mode: same floor, plus true stained-glass optics — the
   *  backdrop renders as TONAL SHADES of the theme hue (sepia re-dye; free color-matrix ops). */
  diffuse?: boolean | "stained";
  /** Brand-gradient accent layered over the material. */
  gradient?: boolean;
  /** Resting glow, or the intensified "lg" halo. */
  glow?: boolean | "lg";
  /** Opt-in hover shimmer (pseudo-element based — avoid on sticky/fixed surfaces). */
  sheen?: boolean;
}

/** The PUBLIC per-instance axis props a component spreads onto its type. Excludes `size` (the material
 *  blur tier is a role-internal detail — a component's own `size` prop owns that name). */
export type MaterialAxisProps = Omit<MaterialProps, "size">;

/** The `rest` side of splitAxisProps. Distributes over union props (DayPicker's mode union, Radix
 *  ToggleGroup's single/multiple) so a discriminated union survives the split instead of collapsing
 *  under a bare Omit. */
export type SplitAxisRest<P> = P extends unknown ? Omit<P, keyof MaterialAxisProps> : never;

/** Split the material axis props off a component's props in ONE place — components never enumerate
 *  axis keys, so a NEW axis is zero-touch: extend MaterialProps + this destructure, done. `size` is
 *  role-internal (not in MaterialAxisProps) and stays in `rest` for the component's own cva. */
export function splitAxisProps<P extends MaterialAxisProps>(
  props: P,
): [
  MaterialAxisProps,
  SplitAxisRest<P>,
] {
  const { material, border, veil, diffuse, gradient, glow, sheen, ...rest } = props;
  return [
    {
      material,
      border,
      veil,
      diffuse,
      gradient,
      glow,
      sheen,
    },
    /* The conditional (distributive) rest type can't be proven for an unresolved P — safe by
     * construction: rest is exactly P minus the axis keys. */
    rest as SplitAxisRest<P>,
  ];
}

export interface MaterialAttrs {
  /** Spread-ready: undefined for adaptive and "none". */
  "data-material"?: Exclude<Material, "none">;
  /** "" when material === "none" (caller supplies its plain classes). */
  className: string;
}

export function glassMaterial(props: MaterialProps = {}): MaterialAttrs {
  const { material, border, veil, size, diffuse, gradient, glow, sheen } = props;
  if (material === "none") {
    return {
      className: "",
    };
  }
  return {
    "data-material": material,
    className: [
      "glass",
      border && "glass-border",
      border === "rim" && "glass-border-rim",
      border === "frame" && "glass-border-frame",
      veil && "glass-veil",
      size === "sm" && "glass-sm",
      size === "lg" && "glass-lg",
      size === "xl" && "glass-xl",
      diffuse && "glass-diffuse",
      diffuse === "stained" && "glass-stained",
      gradient && "glass-gradient",
      glow === "lg" ? "glass-glow-lg" : glow ? "glass-glow" : false,
      sheen && "glass-sheen",
    ]
      .filter(Boolean)
      .join(" "),
  };
}

/**
 * The component-facing resolver: merge a component's ROLE (its default axes for a given semantic
 * variant) with explicit per-instance material/axis props, and return the surface markup — or null
 * when the element is NOT a glass surface (role === null, or material === "none").
 *
 * Explicit props override the role per-axis; unspecified axes fall back to the role.
 */
export function materialSurface(role: MaterialProps | null, props: MaterialProps): MaterialAttrs | null {
  if (props.material === "none" || role === null) {
    return null;
  }
  return glassMaterial({
    material: props.material,
    border: props.border ?? role.border,
    veil: props.veil ?? role.veil,
    size: props.size ?? role.size,
    diffuse: props.diffuse ?? role.diffuse,
    gradient: props.gradient ?? role.gradient,
    glow: props.glow ?? role.glow,
    sheen: props.sheen ?? role.sheen,
  });
}

/**
 * Typed per-element knobs → CSS custom properties ONLY (the cascade-native successor to the old
 * `glass={{…}}` inline-style prop). Everything routes through the token system, so nothing here can
 * fight a material, a page style, or the theme.
 *
 * The tint* keys recolor engine-composed tokens, which re-resolve at grouped declarations — pair
 * them with a `data-glass-tint` attribute on the same element so the engine re-composes there.
 */
export interface GlassVars {
  /** → --glass-tint-h (surface hue) */
  tintH?: number;
  /** → --glass-tint-c (surface chroma — the colorfulness master) */
  tintC?: number;
  /** → --glass-tint-a (tint film alpha) */
  tintA?: number;
  /** → --glass-opacity (0..1 solidify dial; element-composed in `glass`) */
  opacity?: number;
  /** → --srf-blur (number → px; glass material only) */
  blur?: number | string;
  /** → --glass-solid-a (veil floor alpha; element-composed in `glass-veil`) */
  solidA?: number;
}

export function glassVars(v: GlassVars = {}): React.CSSProperties {
  const s: Record<string, string> = {};
  if (v.tintH !== undefined) {
    s["--glass-tint-h"] = String(v.tintH);
  }
  if (v.tintC !== undefined) {
    s["--glass-tint-c"] = String(v.tintC);
  }
  if (v.tintA !== undefined) {
    s["--glass-tint-a"] = String(v.tintA);
  }
  if (v.opacity !== undefined) {
    s["--glass-opacity"] = String(v.opacity);
  }
  if (v.blur !== undefined) {
    s["--srf-blur"] = typeof v.blur === "number" ? `${v.blur}px` : v.blur;
  }
  if (v.solidA !== undefined) {
    s["--glass-solid-a"] = String(v.solidA);
  }
  return s as React.CSSProperties;
}

import { cva } from "class-variance-authority";

/**
 * Shared hover effect variants for all Sistine components
 *
 * Effects:
 * - none: No hover effect
 * - glow: Themed glow shadow (--glass-glow, follows the tint hue) that intensifies on hover
 * - shimmer: Moving shimmer effect across the component
 * - ripple: Ripple effect that scales outward on hover
 * - lift: Subtle lift effect with shadow increase
 * - scale: Scale up slightly on hover
 */
export const hoverEffects = cva("transition duration-300", {
  variants: {
    hover: {
      none: "",
      glow: "glass-glow hover:glass-glow-lg",
      shimmer:
        "relative overflow-hidden before:absolute before:inset-0 before:-translate-x-full before:bg-gradient-to-r before:from-transparent before:via-white/20 before:to-transparent hover:before:translate-x-full before:transition-transform before:duration-1000",
      ripple:
        "relative overflow-hidden after:absolute after:inset-0 after:scale-0 after:rounded-full after:bg-white/30 after:transition-transform after:duration-500 hover:after:scale-150",
      lift: "hover:-translate-y-1 hover:shadow-lg",
      scale: "hover:scale-105",
    },
  },
  defaultVariants: {
    hover: "none",
  },
});

export type HoverEffect = "none" | "glow" | "shimmer" | "ripple" | "lift" | "scale";

import { cva, type VariantProps } from "class-variance-authority";
import { Slot as SlotPrimitive } from "radix-ui";
import type * as React from "react";
import { type HoverEffect, hoverEffects } from "@/lib/hover-effects";
import { type MaterialAxisProps, type MaterialProps, materialSurface, splitAxisProps } from "@/lib/material";
import { cn } from "@/lib/utils";

/* SEMANTIC variants only — each carries BEHAVIOR (text, hover, press shadows); the SURFACE comes from
   the material system (materialSurface below). The four materials + axes are the material/border/veil/
   gradient/glow/sheen props, not variants. */
const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4 shrink-0 [&_svg]:shrink-0 outline-none focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px] aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive active:scale-[0.96] active:transition-transform",
  {
    variants: {
      variant: {
        glass: "text-foreground hover:opacity-90 transition active:opacity-80 active:shadow-[var(--press-shadow-strong)]",
        default:
          "bg-primary text-primary-foreground [background-image:var(--glass-bg)] shadow-[var(--glass-shadow)] hover:brightness-105 dark:hover:brightness-95 transition active:opacity-90 active:shadow-[var(--press-shadow)]",
        destructive:
          "text-destructive border border-destructive/60 hover:opacity-90 transition active:opacity-80 focus-visible:ring-destructive/20 active:shadow-[var(--press-shadow-strong)]",
        outline:
          "text-foreground border-2 border-foreground/20 hover:border-foreground/40 dark:border-white/40 dark:hover:border-white/60 dark:text-white transition active:border-foreground/50 active:shadow-[var(--press-shadow-sm)]",
        secondary: "text-foreground hover:opacity-90 transition active:opacity-80 active:shadow-[var(--press-shadow-strong)]",
        ghost:
          "border border-border hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50 active:bg-accent/80 dark:active:bg-accent/60 active:shadow-[var(--press-shadow-sm)]",
        link: "text-primary underline-offset-4 hover:underline active:opacity-80",
      },
      size: {
        xs: "h-6 gap-1 rounded-md px-2 text-xs has-[>svg]:px-1.5 [&_svg:not([class*='size-'])]:size-3",
        default: "h-9 px-4 py-2 has-[>svg]:px-3",
        sm: "h-8 rounded-md gap-1.5 px-3 has-[>svg]:px-2.5",
        lg: "h-10 rounded-md px-6 has-[>svg]:px-4",
        icon: "size-9",
        "icon-xs": "size-6 rounded-md [&_svg:not([class*='size-'])]:size-3",
        "icon-sm": "size-8",
        "icon-lg": "size-10",
      },
    },
    defaultVariants: {
      variant: "glass",
      size: "default",
    },
  },
);

/* Each semantic variant's surface role: glass = borderless adaptive glass; destructive/outline the
   same (their chrome is their own border); secondary a bordered surface; default/ghost/link render no
   glass surface. */
const SURFACE_ROLE: Record<string, MaterialProps | null> = {
  glass: {},
  destructive: {},
  outline: {
    size: "sm",
  },
  secondary: {
    border: true,
  },
  default: null,
  ghost: null,
  link: null,
};

function Button({
  className,
  variant = "glass",
  size = "default",
  asChild = false,
  effect,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean;
  } & MaterialAxisProps & {
    effect?: HoverEffect;
  }) {
  const Comp = asChild ? SlotPrimitive.Slot : "button";

  const [axes, rest] = splitAxisProps(props);
  const m = materialSurface(SURFACE_ROLE[variant ?? "glass"] ?? null, axes);

  return (
    <Comp
      data-slot="button"
      data-variant={variant}
      data-size={size}
      data-material={m?.["data-material"]}
      data-glass-tint={variant === "destructive" ? "destructive" : undefined}
      className={cn(
        m?.className,
        buttonVariants({
          variant,
          size,
        }),
        effect &&
          hoverEffects({
            hover: effect,
          }),
        className,
      )}
      {...rest}
    />
  );
}

export { Button, buttonVariants };
